import logging


class FadingRegistryEmpty(Exception):
    """Exception which should be raised when no fading is registered"""
    pass


class FadingRegistry(object):
    """Class to keep attenuators loaded from configuration file."""

    def __init__(self):
        self.fading_registry = {}

    def register_fading(self, name, fading_instance):
        """
        Register new attenuator
        :param name: Name of new attenuator from configuration file
        :param att_instance: instance of Attenuator class
        """
        fading_dict = {name: fading_instance}
        self.fading_registry.update(fading_dict)
        logging.info('Adding new fading: {}'.format(name))  # pylint: disable=logging-format-interpolation

    def get_fading(self, name):
        """
        Return attenuator from registry
        :param name: attenuator name
        :return: instance of attenuator
        """
        if not self.fading_registry:
            raise FadingRegistryEmpty('Fading Registry is empty!')
        else:
            return self.fading_registry[name]
